INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (361855, 14897, 'Le Monde', 'en', '''Gender apartheid'': How the Taliban have trampled women''s rights for five years', 'https://www.lemonde.fr/en/summer-reads/article/2026/08/17/gender-apartheid-how-the-taliban-have-trampled-women-s-rights-for-five-years_6756597_183.html', '''Voices of Afghan Women'' (2/6). Upon returning to power on August 15, 2021, the Taliban dismantled institutions, laws and services related to women''s rights in a matter of days and purged the judicial system of all female presence. Here is the next installment of testimonies collected by our reporter in Kabul.', 'https://img.lemde.fr/2026/08/11/562/0/6903/3451/644/322/60/0/9c30721_upload-1-fhsvxes3a9qf-afg-2025-04-02-010.jpg', '2026-08-17T16:01:10+00:00', '2026-08-17T21:41:43.244935'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
