INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (355591, 14898, 'The Times of India', 'en', '''Her memories will always remain in Indian cinema'': Ananya Raj dies at 27; AICWA pays tribute', 'https://timesofindia.indiatimes.com/entertainment/hindi/bollywood/news/ananya-raj-passes-away-at-27-aicwa-pays-tribute-her-memories-will-always-remain-a-part-of-the-indian-film-industry/articleshow/133284294.cms', 'On July 15, the entertainment world mourned the passing of actress Ananya Raj at the young age of twenty-seven. Nearly a month later, her family shared the heartbreaking news, revealing that she had been grappling with severe physical and mental health challenges over the previous year. Ananya was a celebrated figure in both Bollywood and regional films. The Indian Cine Workers Association has voiced deep sorrow for her untimely departure.', 'https://static.toiimg.com/photo/msid-133284347,imgsize-251899.cms', '2026-08-17T01:09:19+00:00', '2026-08-17T04:34:16.731881'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
