INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (363693, 14898, 'Euronews', 'en', '''Such devastating news'': Stars pay tribute to Heroes and Scream star Hayden Panettiere, dead aged 36', 'http://www.euronews.com/culture/2026/08/17/such-devastating-news-stars-pay-tribute-to-heroes-and-scream-star-hayden-panettiere-dead-a', 'Panettiere was best known for her role as cheerleader Claire Bennet in Heroes and country singer Juliette Barnes in Nashville. Stars of cinema and TV, and Hayden Panettiere''s fans, have been paying tribute to the actress, who died aged 36. The cause of her death remains unknown for the time being.', '', '2026-08-17T08:15:07+00:00', '2026-08-17T21:44:10.898175'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
