INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (354436, 14899, 'Aaj Tak', 'hi', 'तीन दिन में 100 करोड़ पार आवारापन 2, पिछड़ी बंटवारा 1947', 'https://www.aajtak.in/entertainment/bollywood-news/story/awarapan-2-batwara-1947-box-office-collection-day-3-emraan-hashmi-leads-first-weekend-sunny-deol-tmovj-dskc-2623509-2026-08-17', 'बंटवारा 1947 वर्सेज आवारापन 2 की बॉक्स ऑफिस भिड़ंत में इमरान की फिल्म आसानी से बाजी मार गई है. पहले हफ्ते उसने सनी देओल की पिक्चर से करीब तीन गुना ज्यादा कमाई की है. तीसरे दिन दोनों ही फिल्मों का हाल कैसा रहा? आइए, आपको बताते हैं...', '', '2026-08-17T01:29:07+00:00', '2026-08-17T02:32:01.226506'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
